from collections import defaultdict
from typing import List

class Solution:
    def maxIntersectionCount(self, y: List[int]) -> int:
        n = len(y)
        events = defaultdict(int)
        for i in range(1, n):
            start = 2 * y[i - 1]
            end = 2 * y[i]
            if i < n - 1:
                if y[i] > y[i - 1]:
                    end -= 1
                else:
                    end += 1
            events[min(start, end)] += 1
            events[max(start, end) + 1] -= 1
        curr = 0
        ans = 0
        for k in sorted(events.keys()):
            curr += events[k]
            ans = max(ans, curr)
        return ans

#include <vector>
#include <map>
#include <algorithm>

class Solution {
public:
    int maxIntersectionCount(std::vector<int>& y) {
        int n = y.size();
        std::map<int, int> events;
        for (int i = 1; i < n; ++i) {
            int start = 2 * y[i - 1];
            int end = 2 * y[i];
            if (i < n - 1) {
                if (y[i] > y[i - 1]) end--;
                else end++;
            }
            events[std::min(start, end)]++;
            events[std::max(start, end) + 1]--;
        }
        int curr = 0, ans = 0;
        for (auto const& [k, v] : events) {
            curr += v;
            ans = std::max(ans, curr);
        }
        return ans;
    }
};

import java.util.TreeMap;
import java.util.Map;

class Solution {
    public int maxIntersectionCount(int[] y) {
        int n = y.length;
        TreeMap<Integer, Integer> events = new TreeMap<>();
        for (int i = 1; i < n; ++i) {
            int start = 2 * y[i - 1];
            int end = 2 * y[i];
            if (i < n - 1) {
                if (y[i] > y[i - 1]) end--;
                else end++;
            }
            int mn = Math.min(start, end);
            int mx = Math.max(start, end);
            events.put(mn, events.getOrDefault(mn, 0) + 1);
            events.put(mx + 1, events.getOrDefault(mx + 1, 0) - 1);
        }
        int curr = 0, ans = 0;
        for (Map.Entry<Integer, Integer> entry : events.entrySet()) {
            curr += entry.getValue();
            ans = Math.max(ans, curr);
        }
        return ans;
    }
}

var maxIntersectionCount = function(y) {
    const n = y.length;
    const events = new Map();
    const add = (k, v) => events.set(k, (events.get(k) || 0) + v);
    for (let i = 1; i < n; ++i) {
        let start = 2 * y[i - 1];
        let end = 2 * y[i];
        if (i < n - 1) {
            if (y[i] > y[i - 1]) end--;
            else end++;
        }
        add(Math.min(start, end), 1);
        add(Math.max(start, end) + 1, -1);
    }
    const sortedKeys = Array.from(events.keys()).sort((a, b) => a - b);
    let curr = 0, ans = 0;
    for (const k of sortedKeys) {
        curr += events.get(k);
        ans = Math.max(ans, curr);
    }
    return ans;
};
